from dataclasses import dataclass, field
from typing import List


@dataclass
class Block:
    name: str
    width: float
    height: float
    x: float = 0.0
    y: float = 0.0
    # Heat generated by the component (relative units)
    power_watts: float = 10.0
    # Component family (ALU, RAM, ...). Used for colouring in the UI.
    kind: str = "CUSTOM"

    def area(self) -> float:
        return self.width * self.height

    def rotate(self) -> None:
        """Rotate by 90 degrees about the block's centre."""
        cx, cy = self.x + self.width / 2, self.y + self.height / 2
        self.width, self.height = self.height, self.width
        self.x, self.y = cx - self.width / 2, cy - self.height / 2


@dataclass
class Net:
    name: str
    connected_blocks: List[Block] = field(default_factory=list)


@dataclass
class Floorplan:
    blocks: List[Block]
    nets: List[Net]
    chip_width: float = 400.0
    chip_height: float = 400.0

    def get_block(self, name: str) -> Block:
        for b in self.blocks:
            if b.name == name:
                return b
        raise ValueError(f"Block {name} not found")

    def unique_name(self, base: str) -> str:
        """Return a block name that is not used yet (base, base_2, base_3, ...)."""
        used = {b.name for b in self.blocks}
        if base not in used:
            return base
        i = 2
        while f"{base}_{i}" in used:
            i += 1
        return f"{base}_{i}"

    def utilization(self) -> float:
        """Fraction of the die covered by block area (can exceed 1.0)."""
        chip_area = self.chip_width * self.chip_height
        return sum(b.area() for b in self.blocks) / chip_area if chip_area > 0 else 0.0
